//! OneClient-style icons as vector shapes on the 24 by 24 icon grid, converted by
//! `tools/vantage-brand/gen_icon_art.py` from supplied artwork. Generated; do not edit by hand.

/// A shape: its outline first, then the holes cut out of it.
pub type Shape = &'static [&'static [[f32; 2]]];

